    15	/* ------------------------------------------------------------------ rules */
    16	
    17	/** A loan runs for 14 days. */
    18	export const LOAN_PERIOD_DAYS = 14;
    19	/** A renewal extends a loan by 7 days. */
    20	export const RENEWAL_PERIOD_DAYS = 7;
