   108	/* ---------------------------------------------------------------- helpers */
   109	
   110	/** ISBNs are compared ignoring case, spaces and hyphens. */
   111	export function normalizeIsbn(isbn: string): string {
   112	  return isbn.replace(/[\s-]/g, '').toUpperCase();
   113	}
   114	
   115	function normalizeEmail(email: string): string {
   116	  return email.trim().toLowerCase();
   117	}
   118	
   119	function later(a: Date | null, b: Date): Date {
   120	  return a !== null && a.getTime() > b.getTime() ? a : b;
   121	}
   122	
   123	function matches(haystack: string, needle: string): boolean {
   124	  return haystack.toLowerCase().includes(needle.toLowerCase());
   125	}
   126	
   127	/** Newest first: most recently borrowed loan leads; ties broken by later due date. */
   128	function newestFirst(a: LoanRecord, b: LoanRecord): number {
   129	  const byBorrowed = b.borrowedAt.getTime() - a.borrowedAt.getTime();
   130	  if (byBorrowed !== 0) return byBorrowed;
   131	  return b.dueAt.getTime() - a.dueAt.getTime();
   132	}
