   145	  /**
   146	   * Add a book. An ISBN that is already known increases the number of owned
   147	   * copies instead of creating a second record.
   148	   */
   149	  addBook(input: unknown): { book: BookView; created: boolean } {
   150	    const body = asObject(input);
   151	    const title = readString(body, 'title');
   152	    const author = readString(body, 'author');
   153	    const isbnRaw = readString(body, 'isbn', 32);
   154	    const isbn = normalizeIsbn(isbnRaw);
   155	    if (isbn === '') {
   156	      throw badRequest('"isbn" must contain at least one letter or digit');
   157	    }
   158	    const copies = readOptionalPositiveInt(body, 'copies') ?? 1;
   159	
   160	    const existing = this.#books.get(this.#booksByIsbn.get(isbn) ?? '');
   161	    if (existing !== undefined) {
   162	      existing.copiesOwned += copies;
   163	      return { book: this.#bookView(existing), created: false };
   164	    }
   165	
   166	    const book: BookRecord = { id: randomUUID(), isbn, isbnRaw, title, author, copiesOwned: copies };
   167	    this.#books.set(book.id, book);
   168	    this.#booksByIsbn.set(isbn, book.id);
   169	    return { book: this.#bookView(book), created: true };
   170	  }
   171	
   172	  listBooks(filter: BookFilter): BookView[] {
   173	    const isbnFilter = filter.isbn === undefined ? undefined : normalizeIsbn(filter.isbn);
   174	    return [...this.#books.values()]
   175	      .filter((book) => {
   176	        if (filter.q !== undefined && !matches(book.title, filter.q) && !matches(book.author, filter.q)) {
   177	          return false;
   178	        }
   179	        if (filter.title !== undefined && !matches(book.title, filter.title)) {
   180	          return false;
   181	        }
   182	        if (filter.author !== undefined && !matches(book.author, filter.author)) {
   183	          return false;
   184	        }
   185	        if (isbnFilter !== undefined && book.isbn !== isbnFilter) {
   186	          return false;
   187	        }
   188	        return true;
   189	      })
   190	      .map((book) => this.#bookView(book));
   191	  }
   192	
   193	  getBook(bookId: string): BookView {
   194	    return this.#bookView(this.#requireBook(bookId));
   195	  }
   196	
   197	  /** Remove a book; refused while any of its copies is on loan. */
   198	  removeBook(bookId: string): void {
   199	    const book = this.#requireBook(bookId);
   200	    const onLoan = this.#activeLoansForBook(book.id);
   201	    if (onLoan.length > 0) {
   202	      throw conflict(
   203	        'BOOK_ON_LOAN',
   204	        `Book "${book.title}" cannot be removed: ${onLoan.length} of ${book.copiesOwned} copies still on loan`,
   205	      );
   206	    }
   207	    this.#books.delete(book.id);
   208	    this.#booksByIsbn.delete(book.isbn);
   209	  }
   210	
   211	  /* ------------------------------------------------------------ members */
   212	
   213	  registerMember(input: unknown, now: Date): MemberView {
   214	    const body = asObject(input);
   215	    const name = readString(body, 'name', 200);
   216	    const emailRaw = readString(body, 'email', 320);
   217	    const email = normalizeEmail(emailRaw);
   218	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
   219	      throw badRequest('"email" must be a valid email address');
   220	    }
   221	    if (this.#membersByEmail.has(email)) {
   222	      throw conflict('DUPLICATE_EMAIL', `A member with email "${email}" already exists`);
   223	    }
   224	    const member: MemberRecord = { id: randomUUID(), name, email, suspendedUntil: null };
   225	    this.#members.set(member.id, member);
   226	    this.#membersByEmail.set(email, member.id);
   227	    return this.#memberView(member, now);
   228	  }
   229	
   230	  listMembers(now: Date): MemberView[] {
   231	    return [...this.#members.values()].map((member) => this.#memberView(member, now));
   232	  }
   233	
   234	  getMember(memberId: string, now: Date): MemberView {
   235	    return this.#memberView(this.#requireMember(memberId), now);
   236	  }
   237	
   238	  /** Suspend a member for `days` (default 7) or until an explicit `until`. */
   239	  suspendMember(memberId: string, input: unknown, now: Date): MemberView {
   240	    const member = this.#requireMember(memberId);
   241	    const body = input === undefined ? {} : asObject(input);
   242	    let until: Date;
   243	    const rawUntil = body['until'];
   244	    if (rawUntil !== undefined) {
   245	      if (typeof rawUntil !== 'string') {
   246	        throw badRequest('"until" must be an ISO-8601 date-time');
   247	      }
   248	      const parsed = new Date(rawUntil);
   249	      if (Number.isNaN(parsed.getTime())) {
   250	        throw badRequest('"until" must be an ISO-8601 date-time');
   251	      }
   252	      if (parsed.getTime() <= now.getTime()) {
   253	        throw badRequest('"until" must be in the future');
   254	      }
   255	      until = parsed;
   256	    } else {
   257	      until = addDays(now, readOptionalPositiveInt(body, 'days') ?? SUSPENSION_DAYS);
   258	    }
   259	    member.suspendedUntil = later(member.suspendedUntil, until);
   260	    return this.#memberView(member, now);
   261	  }
   262	
   263	  /** Lift a suspension early. */
   264	  unsuspendMember(memberId: string, now: Date): MemberView {
   265	    const member = this.#requireMember(memberId);
   266	    member.suspendedUntil = null;
   267	    return this.#memberView(member, now);
   268	  }
   269	
   270	  /* -------------------------------------------------------------- loans */
   271	
   272	  /**
   273	   * Lend a copy to a member for 14 days.
   274	   *
   275	   * Fails when no copy is available, the member is suspended, the member
   276	   * already holds 5 active loans, or the member has an overdue loan.
   277	   */
   278	  borrowBook(input: unknown, now: Date): LoanView {
   279	    const body = asObject(input);
   280	    const member = this.#requireMember(readString(body, 'memberId'));
   281	    const book = this.#requireBook(readString(body, 'bookId'));
   282	
   283	    const available = book.copiesOwned - this.#activeLoansForBook(book.id).length;
   284	    if (available <= 0) {
   285	      throw conflict('NO_COPIES', `No copy of "${book.title}" is available (${book.copiesOwned} owned, all on loan)`);
   286	    }
   287	    if (this.#isSuspended(member, now)) {
   288	      throw conflict(
   289	        'MEMBER_SUSPENDED',
   290	        `Member "${member.name}" is suspended until ${member.suspendedUntil?.toISOString() ?? 'unknown'}`,
   291	      );
   292	    }
   293	    const active = this.#activeLoansForMember(member.id);
   294	    if (active.length >= MAX_ACTIVE_LOANS) {
   295	      throw conflict(
   296	        'LOAN_LIMIT',
   297	        `Member "${member.name}" already has ${active.length} active loans (limit ${MAX_ACTIVE_LOANS})`,
   298	      );
   299	    }
   300	    const overdue = active.find((loan) => loan.dueAt.getTime() < now.getTime());
   301	    if (overdue !== undefined) {
   302	      throw conflict(
   303	        'MEMBER_OVERDUE',
   304	        `Member "${member.name}" has an overdue loan (due ${overdue.dueAt.toISOString()})`,
   305	      );
   306	    }
   307	
   308	    const loan: LoanRecord = {
   309	      id: randomUUID(),
   310	      bookId: book.id,
   311	      memberId: member.id,
   312	      borrowedAt: now,
   313	      dueAt: addDays(now, LOAN_PERIOD_DAYS),
   314	      returnedAt: null,
   315	      renewals: 0,
   316	    };
   317	    this.#loans.set(loan.id, loan);
   318	    return this.#loanView(loan, now);
   319	  }
   320	
   321	  /** Return a copy; a return more than 14 days late suspends the member for 7 days. */
   322	  returnLoan(loanId: string, now: Date): LoanView {
   323	    const loan = this.#requireLoan(loanId);
   324	    if (loan.returnedAt !== null) {
   325	      throw conflict('ALREADY_RETURNED', `Loan ${loan.id} was already returned on ${loan.returnedAt.toISOString()}`);
   326	    }
   327	    loan.returnedAt = now;
   328	
   329	    const lateDays = daysBetween(loan.dueAt, now);
   330	    if (lateDays > LATE_RETURN_DAYS) {
   331	      const member = this.#members.get(loan.memberId);
   332	      if (member !== undefined) {
   333	        member.suspendedUntil = later(member.suspendedUntil, addDays(now, SUSPENSION_DAYS));
   334	      }
   335	    }
   336	    return this.#loanView(loan, now);
   337	  }
   338	
   339	  /**
   340	   * Renew a loan once for 7 more days.
   341	   *
   342	   * Fails while the loan is already overdue, has already been renewed, or the
   343	   * borrowing member is suspended: a suspended member renews nothing.
   344	   */
   345	  renewLoan(loanId: string, now: Date): LoanView {
   346	    const loan = this.#requireLoan(loanId);
   347	    if (loan.returnedAt !== null) {
   348	      throw conflict('ALREADY_RETURNED', `Loan ${loan.id} was already returned`);
   349	    }
   350	    const member = this.#members.get(loan.memberId);
   351	    if (member !== undefined && this.#isSuspended(member, now)) {
   352	      throw conflict(
   353	        'MEMBER_SUSPENDED',
   354	        `Member "${member.name}" is suspended until ${member.suspendedUntil?.toISOString() ?? 'unknown'} and cannot renew loans`,
   355	      );
   356	    }
   357	    if (loan.renewals >= MAX_RENEWALS) {
   358	      throw conflict('ALREADY_RENEWED', `Loan ${loan.id} was already renewed once`);
   359	    }
   360	    if (loan.dueAt.getTime() < now.getTime()) {
   361	      throw conflict('LOAN_OVERDUE', `Loan ${loan.id} is overdue (due ${loan.dueAt.toISOString()}) and cannot be renewed`);
   362	    }
   363	    loan.dueAt = addDays(loan.dueAt, RENEWAL_PERIOD_DAYS);
   364	    loan.renewals += 1;
   365	    return this.#loanView(loan, now);
   366	  }
   367	
   368	  listLoans(filter: LoanFilter, now: Date): LoanView[] {
   369	    return [...this.#loans.values()]
   370	      .filter((loan) => {
   371	        if (filter.memberId !== undefined && loan.memberId !== filter.memberId) return false;
   372	        if (filter.bookId !== undefined && loan.bookId !== filter.bookId) return false;
   373	        if (filter.status !== undefined && this.#loanStatus(loan, now) !== filter.status) return false;
   374	        return true;
   375	      })
   376	      .map((loan) => this.#loanView(loan, now));
   377	  }
   378	
   379	  /**
   380	   * Loan history of one member: every loan, active and returned, newest first
   381	   * (most recently borrowed first). Fails for an unknown member.
   382	   */
   383	  loanHistory(memberId: string, now: Date): LoanView[] {
   384	    const member = this.#requireMember(memberId);
   385	    return [...this.#loans.values()]
   386	      .filter((loan) => loan.memberId === member.id)
   387	      .sort(newestFirst)
   388	      .map((loan) => this.#loanView(loan, now));
   389	  }
   390	
   391	  /** Active loans whose due date is in the past, most overdue first. */
   392	  overdueLoans(now: Date): LoanView[] {
   393	    return [...this.#loans.values()]
   394	      .filter((loan) => loan.returnedAt === null && loan.dueAt.getTime() < now.getTime())
   395	      .sort((a, b) => a.dueAt.getTime() - b.dueAt.getTime())
   396	      .map((loan) => this.#loanView(loan, now));
   397	  }
   398	
   399	  /* ------------------------------------------------------------ private */
   400	
   401	  #requireBook(bookId: string): BookRecord {
   402	    const book = this.#books.get(bookId);
   403	    if (book === undefined) {
   404	      throw notFound(`Book ${bookId} was not found`);
   405	    }
   406	    return book;
   407	  }
   408	
   409	  #requireMember(memberId: string): MemberRecord {
   410	    const member = this.#members.get(memberId);
   411	    if (member === undefined) {
   412	      throw notFound(`Member ${memberId} was not found`);
   413	    }
   414	    return member;
   415	  }
   416	
   417	  #requireLoan(loanId: string): LoanRecord {
   418	    const loan = this.#loans.get(loanId);
   419	    if (loan === undefined) {
   420	      throw notFound(`Loan ${loanId} was not found`);
   421	    }
   422	    return loan;
   423	  }
   424	
   425	  #activeLoansForBook(bookId: string): LoanRecord[] {
   426	    return [...this.#loans.values()].filter((loan) => loan.bookId === bookId && loan.returnedAt === null);
   427	  }
   428	
   429	  #activeLoansForMember(memberId: string): LoanRecord[] {
   430	    return [...this.#loans.values()].filter((loan) => loan.memberId === memberId && loan.returnedAt === null);
   431	  }
   432	
   433	  #isSuspended(member: MemberRecord, now: Date): boolean {
   434	    return member.suspendedUntil !== null && member.suspendedUntil.getTime() > now.getTime();
   435	  }
   436	
   437	  #loanStatus(loan: LoanRecord, now: Date): LoanStatus {
   438	    if (loan.returnedAt !== null) return 'returned';
   439	    return loan.dueAt.getTime() < now.getTime() ? 'overdue' : 'active';
   440	  }
   441	
   442	  #bookView(book: BookRecord): BookView {
   443	    const onLoan = this.#activeLoansForBook(book.id).length;
   444	    return {
   445	      id: book.id,
   446	      isbn: book.isbnRaw,
   447	      title: book.title,
   448	      author: book.author,
   449	      copiesOwned: book.copiesOwned,
   450	      copiesOnLoan: onLoan,
   451	      copiesAvailable: book.copiesOwned - onLoan,
   452	    };
   453	  }
   454	
   455	  #memberView(member: MemberRecord, now: Date): MemberView {
   456	    return {
   457	      id: member.id,
   458	      name: member.name,
   459	      email: member.email,
   460	      suspended: this.#isSuspended(member, now),
   461	      suspendedUntil: member.suspendedUntil === null ? null : member.suspendedUntil.toISOString(),
   462	      activeLoans: this.#activeLoansForMember(member.id).length,
   463	    };
   464	  }
   465	
   466	  #loanView(loan: LoanRecord, now: Date): LoanView {
   467	    const book = this.#books.get(loan.bookId);
   468	    const member = this.#members.get(loan.memberId);
   469	    const end = loan.returnedAt ?? now;
   470	    const daysOverdue = daysBetween(loan.dueAt, end);
   471	    return {
   472	      id: loan.id,
   473	      memberId: loan.memberId,
   474	      bookId: loan.bookId,
   475	      borrowedAt: loan.borrowedAt.toISOString(),
   476	      dueAt: loan.dueAt.toISOString(),
   477	      returnedAt: loan.returnedAt === null ? null : loan.returnedAt.toISOString(),
   478	      renewals: loan.renewals,
   479	      status: this.#loanStatus(loan, now),
   480	      daysOverdue: daysOverdue > 0 ? daysOverdue : 0,
   481	      book: book === undefined ? null : { id: book.id, title: book.title, author: book.author, isbn: book.isbnRaw },
   482	      member: member === undefined ? null : { id: member.id, name: member.name, email: member.email },
   483	    };
   484	  }
   485	}

