     1	/**
     2	 * HTTP layer: plain `node:http`, manual routing, JSON in and JSON out.
     3	 *
     4	 * Every request resolves its own "now" from the `X-Fake-Now` header before the
     5	 * domain layer is called, so time travels per request.
     6	 */
     7	
     8	import type { IncomingMessage, Server, ServerResponse } from 'node:http';
     9	import { createServer as nodeCreateServer } from 'node:http';
    10	
    11	import { resolveNow } from './clock.js';
    12	import { HttpError, badRequest, methodNotAllowed, notFound } from './errors.js';
    13	import { Library, type BookFilter, type LoanFilter, type LoanStatus } from './library.js';
    14	import { readQueryString } from './validate.js';
    15	
    16	export interface LibraryServer {
    17	  server: Server;
    18	  library: Library;
    19	}
    20	
    21	const MAX_BODY_BYTES = 1_000_000;
    22	const LOAN_STATUSES: readonly LoanStatus[] = ['active', 'overdue', 'returned'];
    23	
    24	export function createServer(library: Library = new Library()): LibraryServer {
    25	  const server = nodeCreateServer((req, res) => {
    26	    void handleRequest(library, req, res);
    27	  });
    28	  return { server, library };
    29	}
    30	
    31	async function handleRequest(library: Library, req: IncomingMessage, res: ServerResponse): Promise<void> {
    32	  try {
    33	    await dispatch(library, req, res);
    34	  } catch (error) {
    35	    sendError(res, error);
    36	  }
    37	}
    38	
    39	async function dispatch(
    40	  library: Library,
    41	  req: IncomingMessage,
    42	  res: ServerResponse,
    43	  now = resolveNow(req.headers['x-fake-now']),
    44	): Promise<void> {
    45	  const url = new URL(req.url ?? '/', 'http://localhost');
    46	  const method = (req.method ?? 'GET').toUpperCase();
    47	  const segments = url.pathname
    48	    .split('/')
    49	    .filter((segment) => segment !== '')
    50	    .map((segment) => decodeURIComponent(segment));
    51	
    52	  const head = segments[0];
    53	  const rest = segments.slice(1);
    54	
    55	  if (head === undefined) {
    56	    allow(method, ['GET']);
    57	    json(res, 200, {
    58	      service: 'library',
    59	      status: 'ok',
    60	      resources: ['/health', '/books', '/members', '/loans'],
    61	    });
    62	    return;
    63	  }
    64	
    65	  if (head === 'health') {
    66	    allow(method, ['GET']);
    67	    json(res, 200, { status: 'ok' });
    68	    return;
    69	  }
    70	
    71	  if (head === 'books') {
    72	    await handleBooks(library, req, res, method, rest, url.searchParams);
    73	    return;
    74	  }
    75	
    76	  if (head === 'members') {
    77	    await handleMembers(library, req, res, method, rest, now);
    78	    return;
